<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { studentService } from '../../services/studentService'; import { useTermStore } from '../../stores/useTermStore'
const emit=defineEmits<{close:[]; promoted:[]}>();const store=useTermStore();const summary=ref({graduate:0,junior3:0,junior2:0});const nextYear=computed(()=>Number(store.currentTerm?.academicYear.split('-')[0] ?? new Date().getFullYear())+1);onMounted(async()=>summary.value=await studentService.promotionPreview(nextYear.value));async function confirm(){await studentService.promote(nextYear.value);const academicYear=`${nextYear.value}-${nextYear.value+1}`;const id=`${academicYear}-1`;if(!store.allTerms.some(term=>term.id===id))await store.addTerm({academicYear,semester:1,startDate:`${nextYear.value}-09-01`,endDate:`${nextYear.value+1}-01-20`,isCurrent:true});else await store.setCurrentTerm(id);emit('promoted');emit('close')}
</script><template><div class="fixed inset-0 z-50 flex items-center justify-center bg-stone-950/30 p-4"><section class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl"><h2 class="text-lg font-semibold">新学年升学与归档向导</h2><p class="mt-2 text-sm text-stone-500">即将切换至 {{nextYear}}-{{nextYear+1}} 学年。</p><ul class="mt-5 space-y-3 text-sm"><li>原初三学生：{{summary.graduate}} 名 → 已毕业归档</li><li>原初二学生：{{summary.junior3}} 名 → 初三</li><li>原初一学生：{{summary.junior2}} 名 → 初二</li></ul><div class="mt-6 flex justify-end gap-2"><button class="px-3 py-2 text-sm" @click="emit('close')">取消</button><button class="rounded-lg bg-teal-700 px-3 py-2 text-sm text-white" @click="confirm">确认一键升学</button></div></section></div></template>
